/**
 * Aggregated alert cause by event class and severity.
 */
export type ConnectedAlertCause = { kind: string, severity: string | null, count: number, };

/**
 * Alert delivery metadata using opaque target IDs, never addresses.
 */
export type ConnectedAlertDelivery = { targetKind: string, targetId: string, outcome: string, };

/**
 * Reference to an alert owned by another site, without cross-site finding details.
 */
export type ConnectedAlertElsewhere = { alertId: string,
/**
 * Local project binding, or `None` when another machine owns the binding.
 */
projectId: number | null, projectName: string | null, environmentUrl: string | null, };

/**
 * One read of the connected alert stream, scoped to one project environment.
 */
export type ConnectedAlertFeed = { availability: string,
/**
 * Newest-first timeline rows.
 */
alerts: Array<ConnectedAlert>, elsewhere: Array<ConnectedAlertElsewhere>,
/**
 * Whether the bounded read may have omitted older alerts.
 */
truncated: boolean, };

